import { api } from "./api.js";

export async function fetchUser(id) {
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      return await api.get(`/users/${id}`, { timeout: 10000 });
    } catch (err) {
      if (err.name === "TimeoutError") continue;
      throw err;
    }
  }
  return {};
}

